// ROVER backfill discovery (webhook-driven, cursor-paged, DISCOVERY ONLY).
// Primes secureConfig + CSRF, pages the grid ASC by approval number for a batch of
// pages, returns towing-relevant skeleton rows + a pagination cursor. No detail fetch
// (the expand path does that). The local orchestrator drives pagination + upserts the
// rows into RoverApprovalIndex. Honours 403/429/503 by throwing (caller backs off).
const HOST = 'https://www.rover.infrastructure.gov.au';
const GRID = 'c8825c88-ebd8-ee11-904d-000d3a7a0265';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const KEEP = /^(M[A-E]?|N[ABC]\d?)$/i; // towing-relevant: passenger M*, goods N* (incl. NB/NC trucks)
const helpers = this.helpers;
const payload = ($json && $json.body) ? $json.body : ($json || {});
const PAGE_SIZE = Number(payload.pageSize) || 50;
const START = Number(payload.startPage) || 1;
const BATCH = Math.min(Number(payload.pages) || 10, 25);
const SORT = payload.sort || 'rvr_approvalnumber ASC';
const jar = {};
const cookieHeader = () => Object.entries(jar).map(([k, v]) => k + '=' + v).join('; ');
const absorb = (sc) => (sc || []).forEach((c) => { const p = String(c).split(';')[0]; const i = p.indexOf('='); if (i > 0) jar[p.slice(0, i).trim()] = p.slice(i + 1).trim(); });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const jitter = () => 2500 + Math.floor(Math.random() * 4500);
async function http(method, url, body, extra) {
  const headers = { 'User-Agent': UA, Accept: '*/*', 'Accept-Language': 'en-AU,en;q=0.9', ...(extra || {}) };
  if (Object.keys(jar).length) headers.Cookie = cookieHeader();
  const opts = { method, url, headers, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body != null) { headers['Content-Type'] = 'application/json'; opts.body = body; }
  const res = await helpers.httpRequest(opts);
  absorb(res.headers && (res.headers['set-cookie'] || res.headers['Set-Cookie']));
  if ([403, 429, 503].includes(res.statusCode)) { const ra = res.headers && (res.headers['retry-after'] || res.headers['Retry-After']); const e = new Error('ROVER ' + res.statusCode + ' rate-limit/block'); e.statusCode = res.statusCode; e.retryAfter = ra ? parseInt(ra, 10) : undefined; throw e; }
  if (res.statusCode >= 400) throw new Error('ROVER ' + method + ' ' + url + ' -> ' + res.statusCode);
  return res;
}
const attr = (r, n) => { const a = (r.Attributes || []).find((x) => x.Name === n); return a ? (a.Value && a.Value.Value !== undefined ? a.Value.Value : a.Value) : null; };
const dotnet = (s) => { const m = String(s).match(/\/Date\((\d+)\)\//); return m ? parseInt(m[1], 10) : null; };
try {
  // 1. prime: directory -> secureConfig (+ cookies), then CSRF token
  const dir = await http('GET', HOST + '/PublishedApprovals/VTAApprovals/');
  const vlm = String(dir.body).match(/data-view-layouts=(["'])([\s\S]*?)\1/);
  if (!vlm) throw new Error('data-view-layouts not found — ROVER layout changed');
  const layouts = JSON.parse(Buffer.from(vlm[2].replace(/&quot;/g, '"').replace(/&amp;/g, '&'), 'base64').toString('utf8'));
  const secureConfig = (layouts[0] || {}).Base64SecureConfiguration;
  if (!secureConfig) throw new Error('Base64SecureConfiguration missing');
  const tok = await http('GET', HOST + '/_layout/tokenhtml');
  const token = (String(tok.body).match(/value="([^"]+)"/) || [])[1];
  if (!token) throw new Error('CSRF token not found');
  // 2. page the grid ASC for this batch
  const rows = [];
  let more = false; let lastPage = START - 1;
  for (let p = START; p < START + BATCH; p++) {
    if (p > START) await sleep(jitter());
    const grid = await http('POST', HOST + '/_services/entity-grid-data.json/' + GRID,
      JSON.stringify({ base64SecureConfiguration: secureConfig, sortExpression: SORT, search: null, page: p, pageSize: PAGE_SIZE, filter: null, metaFilter: null }),
      { __RequestVerificationToken: token, 'X-Requested-With': 'XMLHttpRequest' });
    const data = typeof grid.body === 'string' ? JSON.parse(grid.body) : grid.body;
    const recs = data.Records || [];
    lastPage = p;
    for (const r of recs) {
      const cat = String(attr(r, 'cv.rvr_categorytype') || '');
      if (!KEEP.test(cat)) continue;
      const id = attr(r, 'rvr_approvalid') || r.Id;
      if (!id) continue;
      rows.push({ approvalId: id, vta: attr(r, 'rvr_approvalnumber'), make: attr(r, 'cv.rvr_manufacturer'), model: attr(r, 'cv.rvr_model'), category: cat, lastUpdatedMs: dotnet(attr(r, 'rvr_publishedlastupdatedate')) });
    }
    more = !!data.MoreRecords;
    if (!recs.length || !more) { more = false; break; }
  }
  return [{ json: { ok: true, rows, count: rows.length, lastPage, nextPage: more ? lastPage + 1 : null, done: !more } }];
} catch (err) {
  return [{ json: { ok: false, blocked: [403, 429, 503].includes(err.statusCode), status: err.statusCode || null, retryAfter: err.retryAfter || null, error: String(err.message || err) } }];
}
